INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "梁王在贝州休兵", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年正月辛巳", "dynasty": "唐末五代十国", "description": "《通鉴》记梁王在贝州休兵。", "phases": [], "location_name": "贝州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "00718a7a-736a-5540-a19c-ecaeb85c82e0"}, {"title": "杨渥责周隐并处死之", "start_year": 907, "end_year": 907, "time_original": "907年正月条；确日未载", "dynasty": "唐", "description": "杨渥责周隐并处死之。", "phases": [], "location_name": "淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e34776d1-5c93-5b08-8afc-e2bdfaaa77fa"}, {"title": "吕师周惧杨渥而奔湖南", "start_year": 907, "end_year": 907, "time_original": "907年正月条；确日未载", "dynasty": "唐", "description": "吕师周惧杨渥而奔湖南。", "phases": [], "location_name": "上高、湖南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dc2b3102-81bc-5752-b501-e0a0a92cc442"}, {"title": "綦章放吕师周家属离去", "start_year": 907, "end_year": 907, "time_original": "吕师周出奔湖南后；确日未载", "dynasty": "唐", "description": "綦章放吕师周家属离去。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "10cbc5de-1cef-5675-b5a5-b1075e3e029d"}, {"title": "张颢徐温劝谏杨渥而遭怒斥", "start_year": 907, "end_year": 907, "time_original": "907年兵谏前；确日未载", "dynasty": "唐", "description": "张颢徐温劝谏杨渥而遭怒斥。", "phases": [], "location_name": "淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "52a1e942-ba95-5f48-acf8-53264390b87a"}, {"title": "张颢徐温借江西戍守事处死杨渥三名亲兵将领", "start_year": 907, "end_year": 907, "time_original": "907年兵谏前；确日未载", "dynasty": "唐", "description": "张颢徐温借江西戍守事处死杨渥三名亲兵将领。", "phases": [], "location_name": "洪州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "471d85a6-6ceb-5ced-9c8e-4fdf959c15ce"}, {"title": "张颢、徐温发动兵谏，控制淮南军政", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年正月（原文干支作丙戍，待校）", "dynasty": "唐末五代十国", "description": "张颢、徐温率牙兵进入杨渥治事之所，杀其亲信，并逐步控制军政。诛杀三将等前事的具体日期未详。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "75b940f5-52c3-50b3-887c-2d55ad65c36c"}, {"title": "罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年正月", "dynasty": "唐末五代十国", "description": "罗绍威劝梁王尽早灭唐；唐昭宣帝遣薛贻矩至大梁，薛归后报告梁王有受禅之意，唐帝随后提出禅位，梁王辞让。", "phases": [], "location_name": "魏、大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "d65b4d3d-5c8f-5105-bcfd-1633778ed244"}, {"title": "康怀贞奉命屯晋州防备河东军", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年正月条，具体日未载", "dynasty": "唐末五代十国", "description": "梁王命康怀贞征发京兆、同华之兵屯晋州，以防备欲进攻泽州的河东军。", "phases": [], "location_name": "晋州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "035ecc98-3eef-53e7-8c05-2493bfc68957"}, {"title": "唐廷与各镇相继向梁王劝进", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年二月至三月", "dynasty": "唐末五代十国", "description": "唐廷组织百官劝进，三月再遣使传达禅位之意，并安排册礼、传国宝与金宝的奉送人员。杨凝式劝父杨涉辞去送玺之事。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "0ca868ec-69c8-5cb8-81c7-96f889349aab"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

